/// An absolute path, or one rooted at ~ or at ${plugin}, ${workspace} or ${home}, with forward slashes. * matches within a segment and ** across segments.
pub type PathPattern = String;

/// A host name, optionally with a port, or *. followed by a domain to cover its subdomains.
pub type HostPattern = String;

/// A program name looked up on PATH, or an absolute path. No arguments and no whitespace.
pub type Command = String;

/// A command id, or a pattern in which * matches any run of characters, dots included: * covers every command, eris.* every command under eris.
pub type CommandPattern = String;

/// A connector's plugin id, or a pattern in which * matches any run of characters, dots included, like command ids: * covers every connector, endue.* every connector under endue.
pub type ConnectorPattern = String;

/// owner/key: a caller id and a setting key, where * matches any run of characters within its part. endue.eris/voice is one setting; endue.eris/* covers every Eris setting.
pub type SettingPattern = String;

/// A core event that events.subscribe can ask for.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EventName {
    #[serde(rename = "plugin.changed")]
    PluginChanged,
    #[serde(rename = "perm.changed")]
    PermChanged,
    #[serde(rename = "cmd.changed")]
    CmdChanged,
    #[serde(rename = "cmd.invoked")]
    CmdInvoked,
    #[serde(rename = "cmd.undone")]
    CmdUndone,
    #[serde(rename = "settings.changed")]
    SettingsChanged,
    #[serde(rename = "log.entry")]
    LogEntry,
    #[serde(rename = "update.changed")]
    UpdateChanged,
}

/// A plugin manifest (plugin.json).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct PluginManifest {
    pub id: PluginId,
    /// Display name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    pub version: Version,
    pub kind: PluginKind,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub entry: Option<EntryPath>,
    /// One sentence about what the plugin does.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// Everything the plugin may ask for. Each one is still granted by the person at first use.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub permissions: Option<Vec<Permission>>,
    /// Other plugins whose files this plugin's pages load (`../../<id>/…`). Each surface has an origin of its own, so another plugin's files load on it only when named here; their code runs in this plugin's frames, as this plugin and under its grants. Libraries load everywhere without an entry (ADR 0049).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub imports: Option<Vec<PluginId>>,
    /// Surfaces a UI plugin can open. Only UI plugins declare surfaces.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub surfaces: Option<Vec<Surface>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub contributes: Option<PluginContributes>,
    /// The roles this plugin can fill (BR-05, ADR 0104): role:rail, role:agents and role:dock are the desk's three edges, role:palette the command palette, role:settings-ui the settings window. The desk.roles setting chooses each role's provider among the plugins that provide it; a provider that is not chosen does not mount that role's surfaces.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provides: Option<Vec<Role>>,
    /// Installed but off until the desk needs it, like Emacs's autoload. With no stored enabled flag the plugin starts off, and its file openers count while it is off: desk.files turns it on to open a file and off again when its last file closes; profiles leave it as it is. Default false.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub autoload: Option<bool>,
    /// A view plugin's one view, inline; a pack's own view too.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub view: Option<PluginView>,
    /// A view plugin's view files, one PluginView each, relative to the plugin folder; a pack's too.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub views: Option<Vec<ViewPath>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub connector: Option<ConnectorManifest>,
    /// A pack's pack block: what it brings and does when applied (ADR 0108).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pack: Option<PackBlock>,
    /// A theme plugin's theme: its layers and the font and image files it brings, relative to the plugin folder.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub theme: Option<ThemePackage>,
    /// A design-system plugin's design system: what each component of the desk is made of (ADR 0090).
    #[serde(
        rename = "designSystem",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub design_system: Option<DesignSystemPackage>,
}

/// Reverse-domain style id with at least one dot, lowercase, for example endue.eris or example.hello-ui.
pub type PluginId = String;

/// A role a plugin fills: role: and a lowercase name.
pub type Role = String;

/// Semantic version, for example 0.1.0 or 1.2.3-beta.1.
pub type Version = String;

/// ui runs in a sandboxed iframe, logic in a Wasm instance, tool as an MCP server inside the VM. policy runs no code: it only contributes data (ADR 0017). library runs no code of its own either: it is files other plugins import, served at /<id>/... like any plugin's, never mounted and never turned off. connector brings an app's data in as items, as a Wasm component, an MCP server or an http block the core runs (no entry; ADR 0106); view runs no code either: it is one or more views (ADR 0032). theme runs no code: it is a theme block and its font and image files, chosen with desk.theme.active (ADR 0056). design-system runs no code either: it is a designSystem block of component recipes, chosen with desk.design.active (ADR 0090). pack runs no code either: a pack block naming the plugins it brings (nested in its folder or on the desk), its own views and its contributed layout (ADR 0108).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum PluginKind {
    #[serde(rename = "ui")]
    Ui,
    #[serde(rename = "logic")]
    Logic,
    #[serde(rename = "tool")]
    Tool,
    #[serde(rename = "policy")]
    Policy,
    #[serde(rename = "library")]
    Library,
    #[serde(rename = "connector")]
    Connector,
    #[serde(rename = "view")]
    View,
    #[serde(rename = "theme")]
    Theme,
    #[serde(rename = "design-system")]
    DesignSystem,
    #[serde(rename = "pack")]
    Pack,
}

/// Path to the entry file, relative to the plugin folder, without .. segments.
pub type EntryPath = String;

/// A view a plugin provides: a universal view or a page of them (ADR 0087, ADR 0103), with its id, or an item view (ADR 0032; deprecated, read through v0).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum PluginView {
    View(View),
    Universal(UniversalView),
    UniversalPage(UniversalPage),
}

/// A view file relative to the plugin folder, without .. segments: YAML (.yaml, .yml) or JSON (.json).
pub type ViewPath = String;

